package com.acme.reporting.controller;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.expression.Expression;
import org.springframework.expression.ExpressionParser;
import org.springframework.expression.spel.standard.SpelExpressionParser;
import org.springframework.expression.spel.support.StandardEvaluationContext;
import org.springframework.web.bind.annotation.*;
import org.springframework.stereotype.Controller;
import org.springframework.ui.Model;

import com.acme.reporting.service.ReportService;
import com.acme.reporting.model.ReportFilter;

import java.util.Map;
import java.util.HashMap;

@Controller
@RequestMapping("/reports")
public class ReportController {

    @Autowired
    private ReportService reportService;

    private final ExpressionParser parser = new SpelExpressionParser();

    @PostMapping("/generate")
    @ResponseBody
    public Map<String, Object> generateReport(
            @RequestParam("filterExpression") String filterExpression,
            @RequestParam("reportType") String reportType,
            @RequestParam(value = "format", defaultValue = "json") String format) {

        Map<String, Object> response = new HashMap<>();

        try {
            // Parse user-provided filter expression for dynamic report filtering
            StandardEvaluationContext context = new StandardEvaluationContext();
            context.setVariable("reportType", reportType);
            context.setVariable("format", format);
            context.setVariable("reportService", reportService);

            // Evaluate the filter expression to build dynamic query
            Expression exp = parser.parseExpression(filterExpression);
            Object filterResult = exp.getValue(context);

            // Apply filter and generate report
            ReportFilter filter = new ReportFilter();
            filter.setExpression(filterResult != null ? filterResult.toString() : "");
            filter.setType(reportType);

            Object reportData = reportService.generateWithFilter(filter);
            response.put("status", "success");
            response.put("data", reportData);

        } catch (Exception e) {
            response.put("status", "error");
            response.put("message", "Invalid filter expression: " + e.getMessage());
        }

        return response;
    }

    @GetMapping("/templates")
    @ResponseBody
    public Map<String, Object> listTemplates(
            @RequestParam(value = "search", required = false) String search) {

        Map<String, Object> response = new HashMap<>();

        if (search != null && !search.isEmpty()) {
            // Allow SpEL-based search for power users
            StandardEvaluationContext ctx = new StandardEvaluationContext();
            ctx.setVariable("templates", reportService.getAllTemplates());
            Expression searchExp = parser.parseExpression(search);
            Object result = searchExp.getValue(ctx);
            response.put("results", result);
        } else {
            response.put("results", reportService.getAllTemplates());
        }

        return response;
    }

    @PostMapping("/schedule")
    @ResponseBody
    public Map<String, Object> scheduleReport(
            @RequestParam("cronExpression") String cronExpression,
            @RequestParam("reportId") String reportId) {

        Map<String, Object> response = new HashMap<>();
        // Cron validation - not SpEL related
        if (cronExpression.matches("^[0-9*/,\\-\\s]+$")) {
            reportService.schedule(reportId, cronExpression);
            response.put("status", "scheduled");
        } else {
            response.put("status", "invalid_cron");
        }
        return response;
    }
}
